if (threadIdx.x < 32) {
    float v = s[threadIdx.x] + s[threadIdx.x + 32];
    s[threadIdx.x] = v;
    __syncwarp();          // all 32 lanes have written before anyone reads
    for (int off = 16; off > 0; off /= 2) {
        if (threadIdx.x < off) v += s[threadIdx.x + off];
        __syncwarp();      // reads finish before the next writes
        if (threadIdx.x < off) s[threadIdx.x] = v;
        __syncwarp();
    }
}

// assumes blockDim.x == 128
__global__ void blockSum(int* input, int* output)
{
    __shared__ int s[128];
    s[threadIdx.x] = input[blockDim.x * blockIdx.x + threadIdx.x];
    __syncthreads();                    // every write to s is now visible
    if (threadIdx.x == 0) {
        int sum = 0;
        for (int i = 0; i < blockDim.x; ++i) sum += s[i];
        output[blockIdx.x] = sum;       // one result per block
    }
}

